import React, { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isZooming, setIsZooming] = useState(false);

  useEffect(() => {
    // Phase 1: Show letters. Phase 2: Warp Zoom.
    const zoomTimer = setTimeout(() => setIsZooming(true), 2800);
    const completeTimer = setTimeout(onComplete, 3500);
    return () => { clearTimeout(zoomTimer); clearTimeout(completeTimer); };
  }, [onComplete]);

  const letterVariants = {
    initialT1: { x: -100, opacity: 0 },
    initial2: { y: 100, opacity: 0 },
    initialT2: { x: 100, opacity: 0 },
    animate: { x: 0, y: 0, opacity: 1 }
  };

  return (
    <div className="h-screen w-full bg-[#050505] flex items-center justify-center overflow-hidden font-sans">

      {/* Background Grid - Very subtle, tactical */}
      <div className="absolute inset-0 opacity-[0.05] bg-[grid-white_20px_20px] [mask-image:radial-gradient(ellipse_at_center,black,transparent)]" />

      <div className={`relative ${isZooming ? "animate-warp" : ""}`}>
        <div className="flex items-center justify-center gap-4">

          {/* First T */}
          <motion.span 
            variants={letterVariants}
            initial="initialT1"
            animate="animate"
            transition={{ duration: 0.8, ease: "circOut", delay: 0.2 }}
            className="text-8xl md:text-9xl font-[1000] italic text-white tracking-tighter"
          >
            T
          </motion.span>

          {/* The 2 (Brand Color) */}
          <motion.span 
            variants={letterVariants}
            initial="initial2"
            animate="animate"
            transition={{ duration: 0.8, ease: "circOut", delay: 0.4 }}
            className="text-8xl md:text-9xl font-[1000] italic text-shimmer tracking-tighter"
          >
            2
          </motion.span>

          {/* Second T */}
          <motion.span 
            variants={letterVariants}
            initial="initialT2"
            animate="animate"
            transition={{ duration: 0.8, ease: "circOut", delay: 0.6 }}
            className="text-8xl md:text-9xl font-[1000] italic text-white tracking-tighter"
          >
            T
          </motion.span>
        </div>

        {/* Sub-text line */}
        <motion.div 
          initial={{ opacity: 0, letterSpacing: "0em" }}
          animate={{ opacity: 0.4, letterSpacing: "1em" }}
          transition={{ duration: 1.5, delay: 1.2 }}
          className="mt-4 text-center text-white text-[10px] font-bold uppercase"
        >
          Worker_Elite_v3
        </motion.div>
      </div>

      {/* Cinematic Scanline Overlay */}
      <div className="absolute inset-0 pointer-events-none bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.1)_50%)] bg-[length:100%_4px]" />
    </div>
  );
};

export default WorkerSplash;
